patch:
diff --git a/repro/no-unused-expressions-use-strict.js b/repro/no-unused-expressions-use-strict.js
new file mode 100644
index 0000000..13b2802
--- /dev/null
+++ b/repro/no-unused-expressions-use-strict.js
@@ -0,0 +1,20 @@
+"use strict";
+// Repro for: no-unused-expressions reports 'use strict' in 9.25.0 (ES3 files, as in core-js).
+// Usage: node repro/no-unused-expressions-use-strict.js [path/to/eslint/lib/api]
+const path = require("node:path");
+const apiPath = process.argv[2] ? path.resolve(process.argv[2]) : path.join(__dirname, "../lib/api");
+const { Linter } = require(apiPath);
+const version = require(path.join(path.dirname(apiPath), "../package.json")).version;
+
+const code = "'use strict';\nvar a = 1;\n";
+const rules = { "no-unused-expressions": ["error", { allowShortCircuit: true, allowTernary: true, allowTaggedTemplates: true }] };
+const linter = new Linter({ configType: "flat" });
+let failed = false;
+
+for (const ecmaVersion of [3, 5, "latest"]) {
+	const messages = linter.verify(code, [{ files: ["**/*.js"], languageOptions: { ecmaVersion, sourceType: "script" }, rules }], "x.js");
+	const bad = messages.filter(m => m.ruleId === "no-unused-expressions");
+	console.log(`eslint ${version} ecmaVersion=${ecmaVersion}: ${bad.length ? bad.map(m => `${m.line}:${m.column} ${m.message}`).join("; ") : "no errors"}`);
+	if (bad.length) failed = true;
+}
+process.exitCode = failed ? 1 : 0;
